	/**
	 * Default Constructor
	 */
    public TenantService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TenantEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TenantRepository.class) );
		this.validator		= applicationContext.getBean(TenantValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Tenant
	 */
		public Tenant createTenant( CreateTenantCommand command ) {

		Tenant entity = new Tenant();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTenantId( command.getTenantId() );
            entity.setName( command.getName() );
            entity.setTenantType( command.getTenantType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Tenant {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTenantCommand
	 * @return		Tenant
	 */
	public Tenant updateTenant( UpdateTenantCommand command ) {

		Tenant entity = new Tenant();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTenantId( command.getTenantId() );
            entity.setName( command.getName() );
            entity.setSites( command.getSites() );
            entity.setUsers( command.getUsers() );
            entity.setDevices( command.getDevices() );
            entity.setDataRetentionPolicies( command.getDataRetentionPolicies() );
            entity.setConnectivityPlans( command.getConnectivityPlans() );
            entity.setSimCards( command.getSimCards() );
            entity.setMessagingEndpoints( command.getMessagingEndpoints() );
            entity.setAccessPolicies( command.getAccessPolicies() );
            entity.setDeviceGroups( command.getDeviceGroups() );
            entity.setAlertRules( command.getAlertRules() );
            entity.setMaintenanceTickets( command.getMaintenanceTickets() );
            entity.setUsageRecords( command.getUsageRecords() );
            entity.setTenantType( command.getTenantType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Tenant {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTenantCommand
	 */
	public void delete( DeleteTenantCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTenantId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Tenant {0} ", id );

	}

	/**
	 * Method to retrieve the Tenant via TenantFetchOneSummary
	 * @param 	summary TenantFetchOneSummary
	 * @return 	TenantFetchOneResponse
	 */
	public Tenant getTenant( TenantFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TenantFetchOneSummary arg cannot be null" );

		Tenant entity = null;
		UUID id = summary.getTenantId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Tenant using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Tenants
	 *
	 * @return 	List<Tenant>
	 */
    public List<Tenant> getAllTenant() {
		List<Tenant> list = projector.findAll( new FindAllTenantQuery() );
		return list;
	}


